"""AI-authored source-grounded benchmark specifications; no human review claimed."""
from scripts.draft_official_questions import REFUSALS, SPECS

CATEGORIES = {"S": "single_fact", "M": "multi_section", "N": "numeric_date", "C": "cross_document", "V": "version_conflict", "U": "unanswerable", "O": "out_of_scope"}
ROWS = []


def add(split, category, question, answer, facts, *evidence):
    ROWS.append((split, CATEGORIES[category], question, answer,
                 [f.split("|") for f in facts], [tuple(e.split("|", 1)) for e in evidence]))


for i, spec in enumerate(SPECS):
    ROWS.append(("test" if i == 28 else "dev", *spec))
for category, question in REFUSALS[:8]:
    ROWS.append(("dev", category, question, "Refuse: absent from the corpus or outside scope.", [], []))

add("dev", "S", "Under the RBI commercial-bank deposit-interest Directions, what benchmark must floating-rate domestic term deposits use?", "A directly observable, transparent, market-determined external benchmark.", ["external benchmark", "observable", "transparent"], "rbi_md_13157|linked to a directly observable and transparent market determined external benchmark")
add("dev", "S", "Under RBI's deposit-interest Directions, does the normal current-account interest prohibition also mean a deceased individual's balance never earns interest?", "No. The balance earns the applicable savings-deposit rate from death until repayment.", ["savings", "death", "repayment"], "rbi_md_13157|from the date of death of the depositor", "rbi_md_13157|at the rate of interest applicable to savings deposit")
add("dev", "M", "Compare interest treatment of prematurely withdrawn term deposits and matured but unpaid term deposits in RBI's commercial-bank deposit Directions.", "Premature withdrawals use the rate for the actual amount and period, not the contracted rate. Unpaid matured deposits use the lower of savings and contracted rates.", ["period", "contracted", "lower", "savings"], "rbi_md_13157|not at the contracted rate", "rbi_md_13157|on the matured TD, whichever is lower")
add("dev", "M", "Under RBI's commercial-bank card Directions, state the paid-up closure deadline and the Audit Committee's operations-review frequency.", "Closure within seven working days; operations reviewed half-yearly.", ["seven working days|7 working days", "half-yearly|six months"], "rbi_md_13155|honoured within seven working days", "rbi_md_13155|review of their credit card operations on half-yearly basis")
add("dev", "M", "For non-profit customers, name the registration portal in RBI's KYC Directions and the retention period for ordinary transaction records.", "DARPAN Portal of NITI Aayog; transaction records are retained at least five years from the transaction.", ["DARPAN", "five years|5 years"], "rbi_md_13141|DARPAN Portal of NITI Aayog", "rbi_md_13141|at least five years from the date of transaction")
add("dev", "M", "Under RBI's 2026 commercial-bank IO Directions, may the IO have worked for the appointing bank, and what minimum fixed tenure is required?", "Prior employment with that bank is prohibited; the fixed term is at least three years.", ["not|prohibited|no", "three years|3 years"], "rbi_md_13271|shall previously not have been employed", "rbi_md_13271|fixed term of not less than three years")
add("dev", "N", "How long after quarter-end do agency banks have to submit agency-commission claims under RBI's April 2026 Directions?", "60 calendar days after the end of the relevant quarter.", ["60|sixty", "calendar"], "rbi_md_13443|within 60 calendar days, from the end of the quarter")
add("dev", "N", "In SEBI's January 2026 Social Stock Exchange master circular, what minimum public-comment period applies to an NPO's draft fund-raising document?", "At least 21 days.", ["21|twenty-one"], "sebi_md_99166|for a period of at least 21 days for public comments")
add("dev", "N", "Under RBI's deposit-interest Directions, what annual day-count basis is used for FCNR(B) interest?", "360 days to a year.", ["360"], "rbi_md_13157|calculated on the basis of 360 days to a year")
add("dev", "C", "Compare the daily compensation amounts in RBI's delayed credit-information correction and paid-up credit-card closure rules.", "Credit-information correction: Rs 100 per calendar day. Credit-card closure: Rs 500 per calendar day, subject to the respective conditions.", ["100", "500", "calendar"], "rbi_md_13154|a compensation of ₹100 per calendar day", "rbi_md_13155|a penalty of ₹500 per calendar day of delay")
add("dev", "C", "Compare the maximum total IO tenure under RBI's commercial-bank framework with the maximum internal-auditor appointment for SEBI ESG rating providers.", "Both maximum terms are five years; the IO cap includes extensions or reappointment.", ["five years|5 years"], "rbi_md_13271|shall not exceed five years", "sebi_md_95219|a maximum term of five years")
add("dev", "C", "Compare SEBI's annual audit timing for Research Analysts with the time an ESG rating provider has to receive its internal-audit report after year-end.", "RA compliance audit completion: within six months of financial year-end. ERP receipt: within two months of year-end.", ["six months|6 months", "two months|2 months"], "sebi_md_99571|complete the annual compliance audit within six months", "sebi_md_95219|within two months from the end of the year")
add("dev", "C", "Who approves a commercial bank's KYC policy, and who receives the ERP compliance officer's comments on internal-audit observations?", "The bank Board or its delegated committee approves KYC policy; the ERP Board receives the compliance officer's comments.", ["board", "committee"], "rbi_md_13141|any committee to which the Board has delegated power", "sebi_md_95219|place the same before the Board of the ERP")

add("test", "S", "May the original subscriber transfer a Social Stock Exchange ZCZP instrument before its tenure expires, according to the January 2026 SEBI circular?", "No; it is non-transferable until the tenure expires.", ["not|non-transferable|no", "tenure"], "sebi_md_99166|ZCZP shall not be transferable from the original subscriber/ holder")
add("test", "S", "Who prescribes meeting procedures, frequency and quorum for the Social Stock Exchange governing council?", "The Board of the Stock Exchange.", ["board", "stock exchange"], "sebi_md_99166|The Board of the Stock Exchange shall prescribe the procedure")
add("test", "S", "Under RBI's 2026 commercial-bank IO Directions, can the Deputy Internal Ombudsman work for several regulated entities simultaneously?", "No. The Deputy IO cannot be employed by more than one RE simultaneously.", ["not|no", "one"], "rbi_md_13271|shall not be employed in more than one RE simultaneously")
add("test", "S", "To which committee's meetings is the commercial-bank IO a permanent invitee under RBI's 2026 Directions?", "The Customer Service Committee of the Board.", ["Customer Service Committee"], "rbi_md_13271|meetings of the Customer Service Committee of the Board")
add("test", "S", "What extra approval is required for a Pakistani-national student opening the NRO account described in RBI's KYC Directions?", "Prior RBI approval.", ["prior", "RBI|Reserve Bank"], "rbi_md_13141|Students with Pakistani nationality shall require prior approval of the RBI")
add("test", "S", "In Aadhaar OTP e-KYC accounts, which mobile number should receive transaction alerts and OTPs under RBI's KYC Directions?", "The customer's mobile number registered with Aadhaar.", ["registered", "Aadhaar"], "rbi_md_13141|only to the mobile number of the customer registered with Aadhaar")
add("test", "S", "How should wrong debits or contested charges be classified when a commercial bank reports them to credit information companies?", "As disputed, not settled.", ["disputed"], "rbi_md_13154|shall not be reported as 'settled' but as 'disputed'")
add("test", "S", "Under RBI's credit-information reporting Directions, in which reporting category do IBC cases admitted by NCLT or NCLAT belong?", "Suit-filed cases in the Uniform Credit Reporting Format.", ["suit-filed"], "rbi_md_13154|shall be reported under the suit-filed cases")
add("test", "S", "Who bears losses from misuse of an unsolicited credit card under RBI's commercial-bank card Directions?", "The card issuer alone, not the person in whose name it was issued.", ["card-issuer|card issuer"], "rbi_md_13155|shall be the responsibility of the card-issuer only")
add("test", "S", "What data foundation does SEBI specify for a Core ESG Rating in its July 2025 ERP master circular?", "Third-party assured or audited data disclosed by the company.", ["assured", "audited"], "sebi_md_95219|third-party assured or audited data disclosed by the Company")
add("test", "S", "Does the February 2026 SEBI Research Analyst master circular require an RA or research entity to have a website?", "Yes, a functional website.", ["functional website"], "sebi_md_99571|shall maintain a functional website")
add("test", "S", "Does freezing a savings account by an enforcement authority stop regular interest credits under RBI's deposit-interest Directions?", "No. Interest is credited regularly irrespective of operational status.", ["irrespective", "operational"], "rbi_md_13157|irrespective of the operational status of the account")
add("test", "S", "May a bank mark a direct or indirect lien on an NRE savings deposit under RBI's deposit-interest Directions?", "No type of lien is permitted.", ["no|not", "lien"], "rbi_md_13157|shall not mark any type of lien, direct or indirect")
add("test", "S", "Do the RBI commercial-bank deposit-interest Directions apply to operations of Indian banks' foreign branches?", "No, foreign-branch operations are excluded.", ["not|no|excluded", "foreign"], "rbi_md_13157|shall not be applicable to operations of foreign branches")

add("test", "M", "In the January 2026 SSE circular, compare the draft fund-raising document's public-comment period with the exchange's observation deadline.", "At least 21 days for public comments; observations within 30 days of filing or receipt of clarification, whichever is later.", ["21", "30", "later"], "sebi_md_99166|at least 21 days for public comments", "sebi_md_99166|within a time period of 30 days")
add("test", "M", "For ZCZP issuance under SEBI's January 2026 SSE circular, state the minimum subscription percentage and the restriction on transfer by the original holder.", "Minimum subscription is 75%; the original holder cannot transfer before tenure expiry.", ["75", "tenure"], "sebi_md_99166|shall be 75% of the funds proposed to be raised", "sebi_md_99166|till the expiry of the tenure of the said instrument")
add("test", "M", "Compare annual NPO disclosures and quarterly fund-utilization statements under the January 2026 Social Stock Exchange circular.", "Annual disclosures are due within 60 days of financial year-end; fund-utilization statements within 45 days of quarter-end.", ["60", "45"], "sebi_md_99166|within 60 days from end of Financial Year", "sebi_md_99166|within 45 days from the end of quarter")
add("test", "M", "Under SEBI's February 2026 RA circular, how long are client-interaction records normally retained and what happens when a dispute remains unresolved?", "Normally five years; disputed records remain until dispute resolution, with longer retention if SEBI directs it.", ["five years|5 years", "resolution"], "sebi_md_99571|maintain these records for a period of five years", "sebi_md_99571|such records shall be kept till resolution of the dispute")
add("test", "M", "Under RBI's 2026 commercial-bank IO Directions, what are the notification and replacement deadlines for an unexpected IO vacancy?", "Inform RBI within 10 working days; appoint the replacement within three months of vacancy.", ["10 working days|ten working days", "three months|3 months"], "rbi_md_13271|within 10 working days from the date of such vacancy", "rbi_md_13271|within three months from the date of vacancy")
add("test", "M", "Under RBI's 2026 commercial-bank IO Directions, what reporting frequency is preferred and what is the minimum frequency to the Customer Service Committee?", "Quarterly is preferred; reporting must be at least half-yearly.", ["quarterly", "half yearly|half-yearly"], "rbi_md_13271|preferably at quarterly, but not less than half yearly, intervals")
add("test", "M", "Under RBI's KYC Directions, contrast fresh identification CDD for an existing compliant customer's additional account with CDD for joint account holders.", "No fresh identification CDD is needed for an existing KYC-compliant customer's additional account at the same bank; all joint holders require CDD.", ["no|not", "fresh", "all", "joint"], "rbi_md_13141|there shall be no need for a fresh CDD exercise", "rbi_md_13141|follow the CDD Procedure for all the joint account holders")
add("test", "M", "What do RBI's KYC Directions say about confidentiality of account-opening information and using it for cross-selling?", "Treat it as confidential; do not divulge it for cross-selling without express customer permission.", ["confidential", "express", "permission"], "rbi_md_13141|shall treat information collected from customers", "rbi_md_13141|without the express permission of the customer")
add("test", "M", "For ERP internal audits under SEBI's July 2025 circular, what are the report-receipt deadline and final action-taken-report deadline?", "Receive the audit report within two months of year-end. Submit the final action report within two months of receipt or one month of the Board meeting, whichever is later.", ["two months|2 months", "one month|1 month", "later"], "sebi_md_95219|within two months from the end of the year", "sebi_md_95219|1 month from the date of Board Meeting")
add("test", "M", "What is the agency-commission claim deadline and what must accompany late claims under RBI's April 2026 agency-bank Directions?", "60 calendar days after quarter-end; a formal explanation detailing reasons for delay accompanies late claims.", ["60|sixty", "explanation", "delay"], "rbi_md_13443|within 60 calendar days, from the end of the quarter", "rbi_md_13443|a formal explanation, detailing the reasons for the delay")

add("test", "N", "A paid-up credit card is closed four calendar days beyond RBI's deadline. Using the stated daily penalty, calculate the amount payable for those four days.", "Rs 2,000 (4 times Rs 500).", ["2000|2,000"], "rbi_md_13155|a penalty of ₹500 per calendar day of delay")
add("test", "N", "A credit-information correction complaint remains unresolved five calendar days beyond the overall permitted period. At RBI's stated daily compensation, what total corresponds to those five days?", "Rs 500 (5 times Rs 100).", ["500"], "rbi_md_13154|a compensation of ₹100 per calendar day")
add("test", "N", "In the rare temporary absence of both commercial-bank IO and Deputy IO, for how long may the designated serving official act as IO under the 2026 Directions?", "No more than one month, subject to the stated approval and independence conditions.", ["one month|1 month"], "rbi_md_13271|for a period not exceeding one month")
add("test", "N", "How many days does the January 2026 SEBI SSE circular allow for a listed NPO's quarter-end fund-utilization statement?", "45 days from quarter-end.", ["45"], "sebi_md_99166|within 45 days from the end of quarter")
add("test", "N", "What is the minimum membership of the Social Stock Exchange governing council in SEBI's January 2026 circular?", "Seven members, representing the specified categories.", ["7|seven"], "sebi_md_99166|SGC will have a minimum of 7 members")
add("test", "N", "How far ahead of an incumbent IO's expiry must a commercial bank begin a fresh appointment process under RBI's 2026 Directions?", "At least three months in advance.", ["three months|3 months"], "rbi_md_13271|at least three months in advance of the expiry")
add("test", "N", "How many days elapsed from March 31, 2026 to May 15, 2026, and how does that compare numerically with the SSE NPO quarterly-utilization filing window?", "45 days elapsed, equal to the stated 45-day window; this does not certify an actual filing.", ["45"], "sebi_md_99166|within 45 days from the end of quarter")

add("test", "C", "Compare the body overseeing the IO in RBI's 2026 commercial-bank and NBFC Directions.", "Commercial banks use the Customer Service Committee of the Board; NBFCs use their Board.", ["Customer Service Committee", "board"], "rbi_md_13271|meetings of the Customer Service Committee of the Board", "rbi_md_13274|permanent invitee to the meetings of the Board")
add("test", "C", "Compare the ordinary retention periods for KYC transaction records at banks and client-interaction records at Research Analysts, noting the RA dispute exception.", "Both ordinarily require at least five years; RA disputed records remain until dispute resolution, or longer if SEBI directs.", ["five years|5 years", "dispute", "resolution"], "rbi_md_13141|at least five years from the date of transaction", "sebi_md_99571|such records shall be kept till resolution of the dispute")
add("test", "C", "Compare the count and starting event for agency-bank commission claims and SSE NPO annual disclosures in the captured RBI and SEBI sources.", "Both use 60 days: agency claims from quarter-end, NPO annual disclosures from financial year-end.", ["60|sixty", "quarter", "year"], "rbi_md_13443|within 60 calendar days, from the end of the quarter", "sebi_md_99166|within 60 days from end of Financial Year")
add("test", "C", "Compare the fixed-fee cap for investment advisers with the application fee for individual Research Analysts stated in the February 2026 SEBI master circulars.", "IA fixed fee: Rs 1,51,000 per annum per family. Individual RA application fee: Rs 2,000.", ["151000|1,51,000", "2000|2,000"], "sebi_md_99569|shall not exceed ₹1,51,000 per annum per family of client", "sebi_md_99571|Rs. 2,000 Rs. 3,000 Rs. 1,000 Individual and Partnership Firms")

# Version questions are appended below; they distinguish snapshots and explicit saving clauses.
