add("test", "V", "Under clause 17 of RBI's 2026 Small Finance Bank IO Directions, are appointments made under the former IO master direction discarded?", "No. Prior appointments and actions are deemed made under the new Directions.", ["deemed", "appointments"], "rbi_md_13272|All appointments / actions under the aforesaid Master Direction", "rbi_md_13272|shall be deemed to have been made under these Directions")
add("test", "V", "What does the repeal clause in RBI's 2026 NBFC IO Directions identify as the replaced master direction?", "The Internal Ombudsman for Regulated Entities Directions of December 29, 2023.", ["December 29, 2023|2023-12-29", "Internal Ombudsman"], "rbi_md_13274|Directions, 2023 dated December 29, 2023", "rbi_md_13274|issued by the Reserve Bank stands repealed")
add("test", "V", "When the September 2026 SEBI debenture-trustee circular rescinds its predecessor, what happens to an application already made and still pending before SEBI?", "It is deemed made under the corresponding provisions of the new master circular.", ["deemed", "corresponding"], "sebi_md_104743|pending before it shall be deemed to have been made")
add("test", "V", "Does rescission under SEBI's September 2026 debenture-trustee master circular erase previously accrued liabilities or related investigations?", "No. The saving clause preserves accrued liabilities and investigations or proceedings despite rescission.", ["not|no|preserves", "liabilities|liability", "investigation|investigations"], "sebi_md_104743|shall not be affected by such rescission")
add("test", "V", "Does the June 2025 SEBI Research Analyst circular consistently identify the date of the prior master circular in its opening paragraphs?", "No. One paragraph refers to May 21, 2024, while the supersession sentence says May 21, 2025. The conflict cannot be resolved from this text alone.", ["2024", "2025", "conflict|inconsistent|not"], "sebi_md_94840|May 21, 2024", "sebi_md_94840|supersedes the Master Circular for RAs dated May 21, 2025")
